    public static boolean[] module(boolean[] a, boolean[] b) {

        boolean[][] pp = new boolean[64][128];
        genPP0to7(a, b, pp);
        genPP8to15(a, b, pp);
        genPP16to23(a, b, pp);
        genPP24to31(a, b, pp);
        genPP32to39(a, b, pp);
        genPP40to47(a, b, pp);
        genPP48to55(a, b, pp);
        genPP56to63(a, b, pp);

        boolean[] result = accumulate0to15(pp);
        result = accumulate16to31(pp, result);
        result = accumulate32to47(pp, result);
        result = accumulate48to63(pp, result);

        return result;
    }

